    constructor(C _c) {
        c = _c;
    }

    function run(uint ticketAmount, uint extra) public payable {
        require(ticketAmount == 10);
        require(msg.value >= ticketAmount);

        uint bankBefore = c.bank().balance;
        uint cBefore = address(c).balance;

        uint val = ticketAmount + (extra % 5);
        c.play{value: val}();

        uint bankAfter = c.bank().balance;
        uint cAfter = address(c).balance;
        uint potNow = c.pot();

        assert(bankAfter - bankBefore <= cBefore + val - cAfter);
    }

    receive() external payable {}
}

