contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint ticket) public payable {
        uint prePot = c.pot();
        uint preBankBal = c.bank().balance;
        uint preContractBal = address(c).balance;

        require(address(this).balance >= ticket);
        bool reverted;
        try c.play{value: ticket}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint postPot = c.pot();
        uint postBankBal = c.bank().balance;
        uint postContractBal = address(c).balance;

        if (reverted) {
            assert(postPot == prePot && postBankBal == preBankBal && postContractBal == preContractBal);
        } else if (ticket == 10) {
            assert(
                (postPot == 0 && postContractBal == preContractBal && postBankBal == preBankBal) ||
                (postPot == prePot + ticket && postContractBal == preContractBal + ticket && postBankBal == preBankBal)
            );
        } else {
            assert(postPot == prePot && postBankBal == preBankBal && postContractBal == preContractBal);
        }
    }

    receive() external payable {}
}
